mapper.select:
SELECT MS.NO , MS.SEND_NO , MS.RECIEVE_NO , MS.CONTENT , TO_CHAR(MS.SEND_DATE, 'YYYY-MM-DD HH24:MI') AS SEND_DATE , P.NO AS PARTNER_NO , P.NAME AS PARTNER_NAME , D.NAME AS PARTNER_DEPART_NAME , PO.NAME AS PARTNER_POSITION_NAME FROM MESSAGE MS JOIN MEMBER P ON P.NO = MS.RECIEVE_NOMS.SEND_NO LEFT JOIN DEPARTMENT D ON P.DEPART_NO = D.NO LEFT JOIN POSITION PO ON P.POSITION_NO = PO.NO WHERE MS.DEL_YN = 'N' AND MS.MEMBER_NO = #{memberNo}
AND MS.SEND_NO = #{memberNo} AND MS.RECIEVE_NO = #{memberNo}
ORDER BY MS.SEND_DATE DESC, MS.NO DESC FETCH FIRST 200 ROWS ONLY

SELECT COUNT(*)
FROM MEMBER
WHERE NO = #{memberNo}
AND COMPANY_NO = #{companyNo}
AND DEL_YN = 'N'

mapper.insert:
INSERT INTO MESSAGE
(
    NO
    , MEMBER_NO
    , SEND_NO
    , RECIEVE_NO
    , CONTENT
    , SEND_DATE
    , DEL_YN
)
VALUES
(
    SEQ_MESSAGE_NO.NEXTVAL
    , #{ownerNo}
    , #{vo.sendNo}
    , #{vo.recieveNo}
    , #{vo.content}
    , SYSTIMESTAMP
    , 'N'
)

